content.text:
import { isValidDueDate } from '/date-validation.js';

const app = document.querySelector('#app');

function element(tag, text) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  return node;
}

function showError(message) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = element('p');
    alert.setAttribute('role', 'alert');
    app.append(alert);
  }
  alert.textContent = message;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Request failed');
  return body;
}

function projectsButton() {
  const button = element('button', 'Projects');
  button.type = 'button';
  button.addEventListener('click', () => location.assign('/'));
  return button;
}

function projectRow(project, onArchive) {
  const row = element('li');
  row.dataset.testid = 'project-row';
  const button = element('button', 'Open project');
  button.type = 'button';
  button.addEventListener('click', () => location.assign(`/projects/${project.id}`));
  const summary = element('span', `${project.completed}/${project.total} completed`);
  summary.dataset.testid = 'project-summary';
  const archive = element('button', project.archived ? 'Restore project' : 'Archive project');
  archive.type = 'button';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    try {
      const updated = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, updated);
      app.querySelector('[role="alert"]')?.remove();
      onArchive();
    } catch (error) {
      showError(error.message);
    } finally {
      archive.disabled = false;
    }
  });
  row.append(element('span', project.name), summary, button, archive);
  return row;
}

function renderRename(project, heading) {
  const form = element('form');
  const label = element('label', 'New project name');
  label.htmlFor = 'new-project-name';
  const input = element('input');
  input.id = 'new-project-name';
  input.name = 'name';
  input.type = 'text';
  input.disabled = project.archived;
  const submit = element('button', 'Rename project');
  submit.type = 'submit';
  submit.disabled = project.archived;
  form.append(label, input, submit);
  app.append(form);

  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    if (!input.value.trim()) {
      showError('Project name is required');
      return;
    }
    submit.disabled = true;
    try {
      const updated = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: input.value }),
      });
      Object.assign(project, updated);
      heading.textContent = project.name;
      document.title = `${project.name} · Workboard`;
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = project.archived;
    }
  });
}

function taskRenameForm(project, task, endpoint, onRename) {
  const form = element('form');
  const label = element('label', 'New task title');
  const input = element('input');
  input.id = `new-task-title-${task.id}`;
  label.htmlFor = input.id;
  input.name = 'title';
  input.type = 'text';
  input.disabled = project.archived;
  const submit = element('button', 'Rename task');
  submit.type = 'submit';
  submit.disabled = project.archived;
  form.append(label, input, submit);

  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    if (!input.value.trim()) {
      showError('Task title is required');
      return;
    }
    submit.disabled = true;
    try {
      const updated = await request(`${endpoint}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: input.value }),
      });
      task.title = updated.title;
      app.querySelector('[role="alert"]')?.remove();
      onRename();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = project.archived;
    }
  });
  return form;
}

function taskPriorityControl(project, task, endpoint, onPriorityChange) {
  const label = element('label', 'Task priority');
  const select = element('select');
  select.id = `task-priority-${task.id}`;
  label.htmlFor = select.id;
  select.disabled = project.archived;
  for (const priority of ['Low', 'Normal', 'High']) {
    const option = element('option', priority);
    option.value = priority;
    select.append(option);
  }
  select.value = task.priority;
  select.addEventListener('change', async () => {
    select.disabled = true;
    try {
      const updated = await request(`${endpoint}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ priority: select.value }),
      });
      task.priority = updated.priority;
      app.querySelector('[role="alert"]')?.remove();
      onPriorityChange();
    } catch (error) {
      showError(error.message);
    } finally {
      select.value = task.priority;
      select.disabled = project.archived;
    }
  });
  const controls = element('div');
  controls.append(label, select);
  return controls;
}

function taskDueDateForm(project, task, endpoint, onDueDateChange) {
  const form = element('form');
  const label = element('label', 'Task due date');
  const input = element('input');
  input.id = `task-due-date-${task.id}`;
  label.htmlFor = input.id;
  input.type = 'text';
  input.name = 'due_date';
  input.value = task.due_date ?? '';
  input.disabled = project.archived;
  const submit = element('button', 'Save due date');
  submit.type = 'submit';
  submit.disabled = project.archived;
  form.append(label, input, submit);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    submit.disabled = true;
    try {
      const updated = await request(`${endpoint}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ due_date: input.value }),
      });
      task.due_date = updated.due_date;
      input.value = task.due_date;
      app.querySelector('[role="alert"]')?.remove();
      onDueDateChange();
    } catch (error) {
      input.value = task.due_date ?? '';
      showError(error.message);
    } finally {
      submit.disabled = project.archived;
    }
  });
  return form;
}

function taskMoveForm(project, task, endpoint, destinations, onMove) {
  const form = element('form');
  const label = element('label', 'Destination project');
  const select = element('select');
  select.id = `destination-project-${task.id}`;
  label.htmlFor = select.id;
  for (const destination of destinations) {
    const option = element('option', destination.name);
    option.value = String(destination.id);
    select.append(option);
  }
  const disabled = project.archived || destinations.length === 0;
  select.disabled = disabled;
  const submit = element('button', 'Move task');
  submit.type = 'submit';
  submit.disabled = disabled;
  form.append(label, select, submit);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (disabled) return;
    submit.disabled = true;
    select.disabled = true;
    try {
      await request(`${endpoint}/${task.id}/move`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ destination_project_id: Number(select.value) }),
      });
      app.querySelector('[role="alert"]')?.remove();
      onMove();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = disabled;
      select.disabled = disabled;
    }
  });
  return form;
}

function defaultPriorityControl(project) {
  const controls = element('div');
  const label = element('label', 'Default task priority');
  const select = element('select');
  select.id = 'default-task-priority';
  label.htmlFor = select.id;
  select.disabled = project.archived;
  for (const priority of ['Low', 'Normal', 'High']) {
    const option = element('option', priority);
    option.value = priority;
    select.append(option);
  }
  select.value = project.default_priority;
  select.addEventListener('change', async () => {
    if (project.archived) return;
    select.disabled = true;
    try {
      const updated = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ default_priority: select.value }),
      });
      Object.assign(project, updated);
      app.querySelector('[role="alert"]')?.remove();
    } catch (error) {
      showError(error.message);
    } finally {
      select.value = project.default_priority;
      select.disabled = project.archived;
    }
  });
  controls.append(label, select);
  return controls;
}

async function renderTasks(project) {
  const endpoint = `/api/projects/${project.id}/tasks`;
  const form = element('form');
  const titleLabel = element('label', 'Task title');
  titleLabel.htmlFor = 'task-title';
  const input = element('input');
  input.id = 'task-title';
  input.name = 'title';
  input.type = 'text';
  const submit = element('button', 'Create task');
  submit.type = 'submit';
  submit.disabled = project.archived;
  form.append(titleLabel, input, submit);

  const filterLabel = element('label', 'Task filter');
  filterLabel.htmlFor = 'task-filter';
  const filter = element('select');
  filter.id = 'task-filter';
  for (const name of ['All', 'Open', 'Completed']) {
    const option = element('option', name);
    option.value = name;
    filter.append(option);
  }
  const priorityFilterLabel = element('label', 'Priority filter');
  priorityFilterLabel.htmlFor = 'priority-filter';
  const priorityFilter = element('select');
  priorityFilter.id = 'priority-filter';
  for (const name of ['All', 'Low', 'Normal', 'High']) {
    const option = element('option', name);
    option.value = name;
    priorityFilter.append(option);
  }
  const filterControls = element('div');
  filterControls.className = 'task-filter';
  filterControls.append(filterLabel, filter, priorityFilterLabel, priorityFilter);
  const dueRangeForm = element('form');
  const dueFromLabel = element('label', 'Due from');
  const dueFrom = element('input');
  dueFrom.id = 'due-from';
  dueFrom.type = 'text';
  dueFromLabel.htmlFor = dueFrom.id;
  const dueThroughLabel = element('label', 'Due through');
  const dueThrough = element('input');
  dueThrough.id = 'due-through';
  dueThrough.type = 'text';
  dueThroughLabel.htmlFor = dueThrough.id;
  const applyDueRange = element('button', 'Apply due range');
  applyDueRange.type = 'submit';
  dueRangeForm.append(dueFromLabel, dueFrom, dueThroughLabel, dueThrough, applyDueRange);
  // Draft fields are separate from the applied range so invalid submissions
  // and unapplied edits cannot change visible membership.
  let appliedFrom = '';
  let appliedThrough = '';
  const list = element('ul');
  list.setAttribute('aria-label', 'Tasks');
  app.append(defaultPriorityControl(project), form, filterControls, dueRangeForm, list);
  const [tasks, projects] = await Promise.all([request(endpoint), request('/api/projects')]);
  const destinations = projects.filter(destination => !destination.archived && destination.id !== project.id);

  function displayTasks() {
    list.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed) continue;
      if (filter.value === 'Completed' && !task.completed) continue;
      if (priorityFilter.value !== 'All' && task.priority !== priorityFilter.value) continue;
      if (appliedFrom || appliedThrough) {
        if (!task.due_date) continue;
        if (appliedFrom && task.due_date < appliedFrom) continue;
        if (appliedThrough && task.due_date > appliedThrough) continue;
      }
      const row = element('li');
      row.dataset.testid = 'task-row';
      const checkbox = element('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = project.archived;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        try {
          const updated = await request(`${endpoint}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          task.completed = updated.completed;
          app.querySelector('[role="alert"]')?.remove();
          displayTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showError(error.message);
        } finally {
          checkbox.disabled = project.archived;
        }
      });
      row.append(element('span', task.title), checkbox,
        taskRenameForm(project, task, endpoint, displayTasks),
        taskPriorityControl(project, task, endpoint, displayTasks),
        taskDueDateForm(project, task, endpoint, displayTasks),
        taskMoveForm(project, task, endpoint, destinations, () => {
          tasks.splice(tasks.indexOf(task), 1);
          displayTasks();
        }));
      list.append(row);
    }
  }
  dueRangeForm.addEventListener('submit', event => {
    event.preventDefault();
    const from = dueFrom.value.trim();
    const through = dueThrough.value.trim();
    if ((from && !isValidDueDate(from)) || (through && !isValidDueDate(through))) {
      showError('Due range must use valid YYYY-MM-DD dates');
      return;
    }
    if (from && through && from > through) {
      showError('Due from must not be after Due through');
      return;
    }
    appliedFrom = from;
    appliedThrough = through;
    dueFrom.value = from;
    dueThrough.value = through;
    app.querySelector('[role="alert"]')?.remove();
    displayTasks();
  });
  filter.addEventListener('change', displayTasks);
  priorityFilter.addEventListener('change', displayTasks);
  displayTasks();

  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    if (!input.value.trim()) {
      showError('Task title is required');
      return;
    }
    submit.disabled = true;
    try {
      const task = await request(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: input.value }),
      });
      tasks.push(task);
      displayTasks();
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = project.archived;
    }
  });
}

async function render() {
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    app.append(projectsButton());
    const project = await request(`/api/projects/${match[1]}`);
    document.title = `${project.name} · Workboard`;
    const heading = element('h1', project.name);
    app.append(heading);
    if (project.archived) app.append(element('p', 'Archived project'));
    renderRename(project, heading);
    await renderTasks(project);
    return;
  }

  app.append(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  const submit = element('button', 'Create project');
  submit.type = 'submit';
  form.append(label, input, submit);
  const list = element('ul');
  list.setAttribute('aria-label', 'Projects');
  const filterLabel = element('label', 'Project filter');
  filterLabel.htmlFor = 'project-filter';
  const filter = element('select');
  filter.id = 'project-filter';
  for (const name of ['Active', 'Archived']) {
    const option = element('option', name);
    option.value = name;
    filter.append(option);
  }
  const filterControls = element('div');
  filterControls.className = 'task-filter';
  filterControls.append(filterLabel, filter);
  app.append(form, filterControls, list);
  const projects = await request('/api/projects');
  function displayProjects() {
    list.replaceChildren();
    for (const project of projects) {
      if (project.archived === (filter.value === 'Archived')) {
        list.append(projectRow(project, displayProjects));
      }
    }
  }
  filter.addEventListener('change', displayProjects);
  displayProjects();

  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (!input.value.trim()) {
      showError('Project name is required');
      return;
    }
    submit.disabled = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: input.value }),
      });
      projects.push(project);
      displayProjects();
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = false;
    }
  });
}

render().catch(error => showError(error.message)).finally(() => {
  app.setAttribute('aria-busy', 'false');
});

import http from 'node:http';
import { isValidDueDate } from './date-validation.js';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const databasePath = process.env.DB_PATH || './data/workboard.sqlite';
mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
db.exec(`PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);`);
// Existing databases predate archive support; retain their projects and tasks.
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
// Tasks created before priority support keep their identity and default to Normal.
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
// Project defaults only affect future tasks, never existing task priorities.
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
// Empty dates represent tasks with no due date, including migrated tasks.
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
// Legacy ordering column is retained for migration compatibility.
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'position')) {
  db.exec('ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0; UPDATE tasks SET position = id;');
}
// Positions remain reserved even while a task belongs to another project.
// Seed the current order of pre-existing tasks; older moves cannot be inferred.
if (!db.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'task_positions'").get()) {
  db.exec(`BEGIN;
CREATE TABLE task_positions (
  project_id INTEGER NOT NULL REFERENCES projects(id),
  task_id INTEGER NOT NULL REFERENCES tasks(id),
  position INTEGER NOT NULL,
  PRIMARY KEY (project_id, task_id),
  UNIQUE (project_id, position)
);
INSERT INTO task_positions (project_id, task_id, position)
  SELECT project_id, id, ROW_NUMBER() OVER (PARTITION BY project_id ORDER BY position, id) FROM tasks;
COMMIT;`);
}
const listTasks = db.prepare(`SELECT t.id, t.title, t.completed, t.priority, t.due_date
  FROM tasks t JOIN task_positions p ON p.project_id = t.project_id AND p.task_id = t.id
  WHERE t.project_id = ? ORDER BY p.position`);
const findTask = db.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)');
const rememberPosition = db.prepare(`INSERT INTO task_positions (project_id, task_id, position)
  SELECT ?, ?, COALESCE(MAX(position), 0) + 1 FROM task_positions WHERE project_id = ?
  ON CONFLICT (project_id, task_id) DO NOTHING`);
const moveTask = db.prepare('UPDATE tasks SET project_id = ? WHERE project_id = ? AND id = ?');

function transaction(action) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = action();
    db.exec('COMMIT');
    return result;
  } catch (error) {
    db.exec('ROLLBACK');
    throw error;
  }
}
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const prioritizeTask = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const setDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
const taskJson = task => ({ ...task, completed: Boolean(task.completed) });
const projectSelect = `SELECT p.id, p.name, p.archived, p.default_priority,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completed
  FROM projects p`;
const listProjects = db.prepare(`${projectSelect} ORDER BY p.id`);
const findProject = db.prepare(`${projectSelect} WHERE p.id = ?`);
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const archiveProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const setDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const projectJson = project => ({ ...project, archived: Boolean(project.archived) });

const assets = new Map([
  ['/app.js', ['app.js', 'text/javascript; charset=utf-8']],
  ['/style.css', ['style.css', 'text/css; charset=utf-8']],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      const error = new Error('Request is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

const server = http.createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (path === '/api/projects' && request.method === 'GET') {
      return json(response, 200, listProjects.all().map(projectJson));
    }
    if (path === '/api/projects' && request.method === 'POST') {
      const body = await readJson(request);
      const name = typeof body?.name === 'string' ? body.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(response, 201, projectJson(findProject.get(Number(result.lastInsertRowid))));
    }
    const moveMatch = path.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/move$/);
    if (moveMatch && request.method === 'POST') {
      const body = await readJson(request);
      const projectId = Number(moveMatch[1]);
      const taskId = Number(moveMatch[2]);
      const source = findProject.get(projectId);
      if (!source) return json(response, 404, { error: 'Project not found' });
      if (source.archived) return json(response, 409, { error: 'Archived project cannot be changed' });
      if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
      const destinationId = body?.destination_project_id;
      if (!Number.isSafeInteger(destinationId) || destinationId === projectId) {
        return json(response, 400, { error: 'Destination must be another active project' });
      }
      const destination = findProject.get(destinationId);
      if (!destination) return json(response, 404, { error: 'Destination project not found' });
      if (destination.archived) return json(response, 409, { error: 'Destination project is archived' });
      transaction(() => {
        rememberPosition.run(destinationId, taskId, destinationId);
        moveTask.run(destinationId, projectId, taskId);
      });
      return json(response, 200, taskJson(findTask.get(destinationId, taskId)));
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const projectId = Number(tasksMatch[1]);
      const taskId = tasksMatch[2] ? Number(tasksMatch[2]) : null;
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (project.archived && ['POST', 'PATCH'].includes(request.method)) {
        return json(response, 409, { error: 'Archived project cannot be changed' });
      }
      if (taskId === null && request.method === 'GET') {
        return json(response, 200, listTasks.all(projectId).map(taskJson));
      }
      if (taskId === null && request.method === 'POST') {
        const body = await readJson(request);
        const title = typeof body?.title === 'string' ? body.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const result = transaction(() => {
          const inserted = insertTask.run(projectId, title, project.default_priority);
          rememberPosition.run(projectId, inserted.lastInsertRowid, projectId);
          return inserted;
        });
        return json(response, 201, taskJson(findTask.get(projectId, Number(result.lastInsertRowid))));
      }
      if (taskId !== null && request.method === 'PATCH') {
        if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const body = await readJson(request);
        const changes = ['title', 'completed', 'priority', 'due_date'].filter(key => Object.hasOwn(body ?? {}, key));
        if (changes.length > 1) {
          return json(response, 400, { error: 'Task edits must be separate changes' });
        }
        if (changes[0] === 'due_date') {
          const dueDate = typeof body.due_date === 'string' ? body.due_date.trim() : null;
          if (dueDate === null || (dueDate !== '' && !isValidDueDate(dueDate))) {
            return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          setDueDate.run(dueDate, projectId, taskId);
        } else if (changes[0] === 'priority') {
          if (!['Low', 'Normal', 'High'].includes(body.priority)) {
            return json(response, 400, { error: 'Task priority must be Low, Normal, or High' });
          }
          prioritizeTask.run(body.priority, projectId, taskId);
        } else if (changes[0] === 'title') {
          const title = typeof body.title === 'string' ? body.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
        } else {
          if (typeof body?.completed !== 'boolean') {
            return json(response, 400, { error: 'Task completion must be a boolean' });
          }
          updateTask.run(Number(body.completed), projectId, taskId);
        }
        return json(response, 200, taskJson(findTask.get(projectId, taskId)));
      }
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (projectMatch && ['GET', 'PATCH'].includes(request.method)) {
      const projectId = Number(projectMatch[1]);
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'PATCH') {
        const body = await readJson(request);
        const changes = ['name', 'archived', 'default_priority'].filter(key => Object.hasOwn(body ?? {}, key));
        if (changes.length > 1) {
          return json(response, 400, { error: 'Project edits must be separate changes' });
        }
        if (changes[0] === 'default_priority') {
          if (project.archived) {
            return json(response, 409, { error: 'Archived project cannot be changed' });
          }
          if (!['Low', 'Normal', 'High'].includes(body.default_priority)) {
            return json(response, 400, { error: 'Default task priority must be Low, Normal, or High' });
          }
          setDefaultPriority.run(body.default_priority, projectId);
        } else if (changes[0] === 'name') {
          if (project.archived) {
            return json(response, 409, { error: 'Archived project cannot be changed' });
          }
          const name = typeof body.name === 'string' ? body.name.trim() : '';
          if (!name) return json(response, 400, { error: 'Project name is required' });
          renameProject.run(name, projectId);
        } else {
          if (typeof body?.archived !== 'boolean') {
            return json(response, 400, { error: 'Project archive state must be a boolean' });
          }
          archiveProject.run(Number(body.archived), projectId);
        }
      }
      return json(response, 200, projectJson(findProject.get(projectId)));
    }
    if (request.method === 'GET' && path === '/date-validation.js') {
      const contents = await readFile(new URL('./date-validation.js', import.meta.url));
      response.writeHead(200, { 'Content-Type': 'text/javascript; charset=utf-8' });
      return response.end(contents);
    }
    if (request.method === 'GET' && (path === '/' || /^\/projects\/\d+$/.test(path) || assets.has(path))) {
      const [file, contentType] = assets.get(path) || ['index.html', 'text/html; charset=utf-8'];
      const contents = await readFile(new URL(`./public/${file}`, import.meta.url));
      response.writeHead(200, { 'Content-Type': contentType });
      return response.end(contents);
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    json(response, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    db.close();
    process.exit(0);
  }));
}

{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import vm from 'node:vm';
import { isValidDueDate } from '../date-validation.js';

// Minimal DOM surface for testing task controls without browser dependencies.
class Element {
  constructor(tag) {
    this.tagName = tag;
    this.children = [];
    this.listeners = {};
    this.attributes = {};
    this.dataset = {};
    this.value = '';
  }
  append(...children) {
    this.children.push(...children);
    if (this.tagName === 'select' && !this.value && children.length) {
      this.value = children[0].value;
    }
  }
  focus() {}
  replaceChildren(...children) { this.children = children; }
  setAttribute(name, value) { this.attributes[name] = value; }
  addEventListener(name, listener) { this.listeners[name] = listener; }
  querySelector() { return null; }
}

async function setup(fetch) {
  const app = new Element('main');
  const context = vm.createContext({
    document: {
      querySelector: () => app,
      createElement: tag => new Element(tag),
    },
    location: { pathname: '/' },
    fetch,
    isValidDueDate,
  });
  const source = await readFile(new URL('../public/app.js', import.meta.url), 'utf8');
  vm.runInContext(`${source.replace(/^import .*;\n/, '')}\nglobalThis.priorityControl = taskPriorityControl;\nglobalThis.renderTasks = renderTasks;`, context);
  // Let the initial project-list render finish before exercising project controls.
  await new Promise(resolve => setImmediate(resolve));
  app.replaceChildren();
  return { control: context.priorityControl, renderTasks: context.renderTasks, app };
}

test('priority UI labels options, saves changes, and rolls back failed changes', async () => {
  const requests = [];
  let fail = false;
  const { control } = await setup(async (path, options) => {
    if (!options) return { ok: true, json: async () => [] };
    requests.push({ path, body: JSON.parse(options.body), method: options.method });
    return {
      ok: !fail,
      json: async () => fail ? { error: 'Unable to save' } : { priority: JSON.parse(options.body).priority },
    };
  });
  const task = { id: 7, title: 'Keep title', completed: true, priority: 'Normal' };
  let changes = 0;
  const [label, select] = control({ archived: false }, task, '/api/projects/2/tasks', () => changes++).children;
  assert.equal(label.textContent, 'Task priority');
  assert.equal(label.htmlFor, select.id);
  assert.deepEqual(Array.from(select.children, option => option.textContent), ['Low', 'Normal', 'High']);
  assert.equal(select.value, 'Normal');
  assert.equal(select.disabled, false);
  select.value = 'High';
  await select.listeners.change();
  assert.deepEqual(requests, [{ path: '/api/projects/2/tasks/7', body: { priority: 'High' }, method: 'PATCH' }]);
  assert.deepEqual(task, { id: 7, title: 'Keep title', completed: true, priority: 'High' });
  assert.equal(select.value, 'High');
  assert.equal(select.disabled, false);
  fail = true;
  select.value = 'Low';
  await select.listeners.change();
  assert.equal(task.priority, 'High');
  assert.equal(changes, 1);
  assert.equal(select.value, 'High');
  assert.equal(select.disabled, false);
});

test('archived priority controls are disabled and restoration keeps their value', async () => {
  const { control } = await setup(async () => ({ ok: true, json: async () => [] }));
  const task = { id: 3, priority: 'Low' };
  const archived = control({ archived: true }, task, '/api/projects/1/tasks').children[1];
  assert.equal(archived.disabled, true);
  assert.equal(archived.value, 'Low');
  const restored = control({ archived: false }, task, '/api/projects/1/tasks').children[1];
  assert.equal(restored.disabled, false);
  assert.equal(restored.value, 'Low');
});

function descendants(node) {
  return node.children.flatMap(child => [child, ...descendants(child)]);
}

async function projectUI(archived = false, dueDates = [], projects = []) {
  const tasks = [
    { id: 1, title: 'High open', priority: 'High', completed: false },
    { id: 2, title: 'Low done', priority: 'Low', completed: true },
    { id: 3, title: 'Normal open', priority: 'Normal', completed: false },
    { id: 4, title: 'High done', priority: 'High', completed: true },
    { id: 5, title: 'Low open', priority: 'Low', completed: false },
    { id: 6, title: 'Normal done', priority: 'Normal', completed: true },
  ];
  tasks.forEach((task, index) => { task.due_date = dueDates[index] ?? ''; });
  const requests = [];
  const { app, renderTasks } = await setup(async (path, options) => {
    let body = [];
    if (path.endsWith('/tasks')) body = tasks;
    if (path === '/api/projects') body = projects;
    if (options) {
      const changes = JSON.parse(options.body);
      requests.push({ path, changes });
      body = options.method === 'POST'
        ? { id: tasks.length + 1, ...changes, priority: 'Normal', completed: false, due_date: '' }
        : { ...tasks.find(task => path.endsWith(`/${task.id}`)), ...changes };
    }
    return { ok: true, json: async () => body };
  });
  const project = { id: 1, archived, default_priority: 'Normal' };
  await renderTasks(project);
  const nodes = () => descendants(app);
  const byId = id => nodes().find(node => node.id === id);
  const rows = () => nodes().filter(node => node.dataset.testid === 'task-row');
  const titles = () => rows().map(row => row.children[0].textContent);
  const change = async (id, value) => {
    const control = byId(id);
    control.value = value;
    await control.listeners.change();
  };
  return { app, project, tasks, requests, nodes, byId, rows, titles, change };
}

test('move controls list only eligible destinations and retain source filters after moving', async () => {
  const projects = [
    { id: 1, name: 'Source', archived: false },
    { id: 2, name: 'Renamed destination', archived: false },
    { id: 3, name: 'Archived', archived: true },
    { id: 4, name: 'Last destination', archived: false },
  ];
